import test from 'node:test';import assert from 'node:assert/strict';import fixture from './vantor-native.fixture.json' with {type:'json'};import {validatePublicDatasetPlan,validatePublicDatasetConnection,validatePublicDatasetItem,publicDatasetAssetLayer} from './public-dataset-client.js';
test('actual Vantor native plan and item retain the September acquisition instant and exact source/area/proof',()=>{const {connection,snapshot}=fixture,plan=connection.plan;assert.equal(validatePublicDatasetPlan(plan,plan.request),plan);assert.equal(validatePublicDatasetConnection(connection,plan.request),connection);assert.equal(validatePublicDatasetItem(snapshot,plan,connection.stacConnections),snapshot);assert.equal(snapshot.datetime,'2026-09-07T05:07:53.249593Z');assert.equal(publicDatasetAssetLayer(plan.dataset,plan.request,'visual').id,'visual');assert.equal(publicDatasetAssetLayer(plan.dataset,plan.request,'ms'),null);});
test('allowing the finite Vantor point-time product does not admit a different month, bounds, source pin or original time',()=>{const {connection,snapshot}=fixture,plan=connection.plan;for(const mutate of [p=>p.request.month=8,p=>p.request.bounds[0]=85.43,p=>p.sources[0].stac.kind='raster']){const changed=structuredClone(plan);mutate(changed);assert.throws(()=>validatePublicDatasetPlan(changed,plan.request));}for(const mutate of [s=>s.datetime='2026-08-07T05:07:53.249593Z',s=>s.bbox[0]=85.3,s=>s.provenance.reviewedDataset.request.month=8,s=>s.provenance.documentUrl='https://vantor-opendata.s3.amazonaws.com/other.json']){const changed=structuredClone(snapshot);mutate(changed);assert.throws(()=>validatePublicDatasetItem(changed,plan,connection.stacConnections));}});
